package cl.duoc.medialert;import java.time.Instant;import java.util.*;import java.util.concurrent.atomic.AtomicLong;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Service;@Service public class ProcesamientoService{private final KafkaTemplate<String,AlertaEvento> kafka;private final AtomicLong procesadas=new AtomicLong(),alertas=new AtomicLong();public ProcesamientoService(KafkaTemplate<String,AlertaEvento> k){kafka=k;}@KafkaListener(topics="senales_vitales",groupId="procesador-senales") public void consumir(SenalVital s){procesadas.incrementAndGet();List<String> d=new ArrayList<>();if(s.frecuenciaCardiaca()<50||s.frecuenciaCardiaca()>120)d.add("Frecuencia cardíaca fuera de rango: "+s.frecuenciaCardiaca());if(s.presionSistolica()<90||s.presionSistolica()>160)d.add("Presión sistólica fuera de rango: "+s.presionSistolica());if(s.presionDiastolica()<60||s.presionDiastolica()>100)d.add("Presión diastólica fuera de rango: "+s.presionDiastolica());if(s.temperatura()<35||s.temperatura()>=38)d.add("Temperatura fuera de rango: "+s.temperatura());if(!d.isEmpty()){String sev=(s.frecuenciaCardiaca()>140||s.presionSistolica()>180||s.temperatura()>=39)?"CRITICA":"ALTA";var a=new AlertaEvento(s.pacienteId(),"SIGNOS_VITALES",String.join("; ",d),sev,Instant.now());kafka.send("alertas",String.valueOf(s.pacienteId()),a);alertas.incrementAndGet();}}public Map<String,Object> estado(){return Map.of("servicio","procesador-senales","estado","UP","senalesProcesadas",procesadas.get(),"alertasPublicadas",alertas.get());}}